1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8	)
9	
10	// RecordInfo 描述一次保存产生的记录的元信息。
11	type RecordInfo struct {
12		// ID 是记录在存档目录内的唯一标识。
13		ID RecordID
14		// Parent 是父记录标识；直接建立的槽首条记录为空。
15		Parent RecordID
16		// SlotFirst 表示这是所在槽的首条记录（根记录或分支记录）。
17		SlotFirst bool
18		// Version 是记录中世界规则的版本。
19		Version string
20	}
21	
22	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
23	type slotPointer struct {
24		Latest RecordID `json:"latest"`
25	}
26	
27	// archiveMarker 是存档目录的标记文件。
28	type archiveMarker struct {
29		Format int `json:"format"`
30	}
31	
32	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
33	// 同一目录；所有写入通过目录内的 flock 串行化。
34	type Archive struct {
35		dir string
36	}
37	
38	const (
39		markerName  = "archive.json"
40		recordsName = "records"
41		slotsName   = "slots"
42	)
43	
44	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
45	// 存档则返回错误，以免覆盖已有数据。
46	func Create(dir string) (*Archive, error) {
47		if err := os.MkdirAll(dir, 0o755); err != nil {
48			return nil, err
49		}
50		markerPath := filepath.Join(dir, markerName)
51		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
52		if err != nil {
53			if errors.Is(err, os.ErrExist) {
54				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
55			}
56			return nil, err
57		}
58		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
59		if _, err := f.Write(markerData); err != nil {
60			f.Close()
61			return nil, err
62		}
63		if err := f.Close(); err != nil {
64			return nil, err
65		}
66		for _, sub := range []string{recordsName, slotsName} {
67			if err := os.MkdirAll(filepath.Join(dir, sub), 0o755); err != nil {
68				return nil, err
69			}
70		}
71		// 预先建立锁文件并同步目录，使之后的打开更稳妥。
72		if lf, err := os.OpenFile(filepath.Join(dir, "lock"),
73			os.O_RDWR|os.O_CREATE, 0o600); err == nil {
74			lf.Close()
75		}
76		if err := syncDir(dir); err != nil {
77			return nil, err
78		}
79		return &Archive{dir: dir}, nil
80	}
81	
82	// Open 打开一个此前由 Create 建立的存档目录。
83	func Open(dir string) (*Archive, error) {
84		path := filepath.Join(dir, markerName)
85		f, err := os.Open(path)
86		if err != nil {
87			if errors.Is(err, os.ErrNotExist) {
88				return nil, &NotFoundError{}
89			}
90			return nil, err
91		}
92		defer f.Close()
93		var m archiveMarker
94		if err := json.NewDecoder(f).Decode(&m); err != nil {
95			return nil, &CorruptError{Reason: "存档标记无法解析"}
96		}
97		if m.Format != archiveFormatVersion {
98			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
99		}
100		for _, sub := range []string{recordsName, slotsName} {
101			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
102				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
103			}
104		}
105		return &Archive{dir: dir}, nil
106	}
107	
108	// Dir 返回存档目录路径。
109	func (a *Archive) Dir() string { return a.dir }
110	
111	func (a *Archive) slotPath(slot string) string {
112		return filepath.Join(a.dir, slotsName, slot+".json")
113	}
114	
115	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
116	func validSlotName(slot string) bool {
117		if slot == "" || slot == "." || slot == ".." {
118			return false
119		}
120		if filepath.IsAbs(slot) {
121			return false
122		}
123		for _, r := range slot {
124			if r == '/' || r == '\\' || r == 0 {
125				return false
126			}
127		}
128		return filepath.Clean(slot) == slot
129	}
130	
131	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
132	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
133		data, err := os.ReadFile(a.slotPath(slot))
134		if err != nil {
135			if errors.Is(err, os.ErrNotExist) {
136				return "", &NotFoundError{Slot: slot}
137			}
138			return "", err
139		}
140		var p slotPointer
141		if err := json.Unmarshal(data, &p); err != nil {
142			return "", &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
143		}
144		if p.Latest == "" {
145			return "", &CorruptError{Slot: slot, Reason: "槽指针为空"}
146		}
147		return p.Latest, nil
148	}
149	
150	// Save 在存档中保存一个世界。
151	//
152	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
153	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
154	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
155		if !validSlotName(slot) {
156			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
157		}
158		st := w.Snapshot()
159	
160		lock, err := acquireLock(a.dir)
161		if err != nil {
162			return RecordInfo{}, err
163		}
164		defer lock.release()
165	
166		// 持锁后再次确认槽不存在。
167		if _, err := a.readLatestLocked(slot); err == nil {
168			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
169		} else if !errors.As(err, new(*NotFoundError)) {
170			return RecordInfo{}, err
171		}
172	
173		id, err := newRecordID()
174		if err != nil {
175			return RecordInfo{}, err
176		}
177		env := &envelope{
178			Format:    archiveFormatVersion,
179			ID:        id,
180			SlotFirst: true,
181			State:     st,
182		}
183		env.Checksum = computeChecksum(env)
184		if err := writeRecord(a.dir, env); err != nil {
185			return RecordInfo{}, err
186		}
187		if err := a.createSlotPointer(slot, id); err != nil {
188			return RecordInfo{}, err
189		}
190		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
191	}
192	
193	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
194	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
195	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。
196	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
197		slotsDir := filepath.Join(a.dir, slotsName)
198		final := a.slotPath(slot)
199		data, _ := json.MarshalIndent(slotPointer{Latest: id}, "", "  ")
200	
201		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
202		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
203		if err != nil {
204			return err
205		}
206		if _, err := f.Write(data); err != nil {
207			f.Close()
208			os.Remove(tmp)
209			return err
210		}
211		if err := f.Sync(); err != nil {
212			f.Close()
213			os.Remove(tmp)
214			return err
215		}
216		if err := f.Close(); err != nil {
217			os.Remove(tmp)
218			return err
219		}
220		if err := os.Link(tmp, final); err != nil {
221			os.Remove(tmp)
222			if errors.Is(err, os.ErrExist) {
223				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
224			}
225			return err
226		}
227		os.Remove(tmp)
228		return syncDir(slotsDir)
229	}
230	
231	// Replace 用世界当前状态覆盖槽的最新记录。
232	//
233	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
234	// 写入才会发生；否则返回 *ConflictError。新记录的父记录就是被覆盖的
235	// 那次记录。同一目录下并发覆盖同一父记录时只有一个成功。
236	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
237		if !validSlotName(slot) {
238			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
239		}
240		if expected == "" {
241			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
242		}
243		st := w.Snapshot()
244	
245		lock, err := acquireLock(a.dir)
246		if err != nil {
247			return RecordInfo{}, err
248		}
249		defer lock.release()
250	
251		latest, err := a.readLatestLocked(slot)
252		if err != nil {
253			return RecordInfo{}, err
254		}
255		if latest != expected {
256			return RecordInfo{}, &ConflictError{
257				Slot:   slot,
258				Reason: "所依据的记录已不是该槽最新记录",
259			}
260		}
261	
262		id, err := newRecordID()
263		if err != nil {
264			return RecordInfo{}, err
265		}
266		env := &envelope{
267			Format: archiveFormatVersion,
268			ID:     id,
269			Parent: expected,
270			State:  st,
271		}
272		env.Checksum = computeChecksum(env)
273		if err := writeRecord(a.dir, env); err != nil {
274			return RecordInfo{}, err
275		}
276		if err := a.replaceSlotPointer(slot, id); err != nil {
277			return RecordInfo{}, err
278		}
279		return RecordInfo{
280			ID:      id,
281			Parent:  expected,
282			Version: st.Rules.Version,
283		}, nil
284	}
285	
286	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
287		data, _ := json.MarshalIndent(slotPointer{Latest: id}, "", "  ")
288		if err := writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data); err != nil {
289			return err
290		}
291		return nil
292	}
293	
294	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
295	//
296	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
297	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
298	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
299		if !validSlotName(srcSlot) {
300			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
301		}
302		if !validSlotName(dstSlot) {
303			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
304		}
305		if src == "" {
306			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
307		}
308	
309		lock, err := acquireLock(a.dir)
310		if err != nil {
311			return RecordInfo{}, err
312		}
313		defer lock.release()
314	
315		srcEnv, err := a.loadAndVerifyLocked(src)
316		if err != nil {
317			return RecordInfo{}, err
318		}
319		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
320		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
321			return RecordInfo{}, err
322		}
323		// 目标槽重名拒绝创建。
324		if _, err := a.readLatestLocked(dstSlot); err == nil {
325			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
326		} else if !errors.As(err, new(*NotFoundError)) {
327			return RecordInfo{}, err
328		}
329	
330		id, err := newRecordID()
331		if err != nil {
332			return RecordInfo{}, err
333		}
334		env := &envelope{
335			Format:    archiveFormatVersion,
336			ID:        id,
337			Parent:    src,
338			SlotFirst: true,
339			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
340			State: cloneState(srcEnv.State),
341		}
342		env.Checksum = computeChecksum(env)
343		if err := writeRecord(a.dir, env); err != nil {
344			return RecordInfo{}, err
345		}
346		if err := a.createSlotPointer(dstSlot, id); err != nil {
347			return RecordInfo{}, err
348		}
349		return RecordInfo{
350			ID:        id,
351			Parent:    src,
352			SlotFirst: true,
353			Version:   env.State.Rules.Version,
354		}, nil
355	}
356	
357	// assertInSlotHistoryLocked 确认 id 位于 slot 的历史链上（不含越界到
358	// 其他槽的父记录）。
359	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
360		chain, err := a.slotChainLocked(slot)
361		if err != nil {
362			return err
363		}
364		for _, cid := range chain {
365			if cid == id {
366				return nil
367			}
368		}
369		return &NotFoundError{Slot: slot, Record: id}
370	}
371	
372	// slotChainLocked 返回槽的历史记录标识，最新在前，在该槽首条记录处
373	// 停止（不跨入分支来源槽）。
374	func (a *Archive) slotChainLocked(slot string) ([]RecordID, error) {
375		latest, err := a.readLatestLocked(slot)
376		if err != nil {
377			return nil, err
378		}
379		var chain []RecordID
380		seen := map[RecordID]bool{}
381		cur := latest
382		for cur != "" {
383			if seen[cur] {
384				return nil, &CorruptError{Slot: slot, Record: cur, Reason: "历史链出现环"}
385			}
386			seen[cur] = true
387			env, err := loadRecord(recordPath(a.dir, cur))
388			if err != nil {
389				if errors.Is(err, os.ErrNotExist) {
390					return nil, &CorruptError{Slot: slot, Record: cur, Reason: "历史记录文件缺失"}
391				}
392				return nil, &CorruptError{Slot: slot, Record: cur, Reason: err.Error()}
393			}
394			chain = append(chain, cur)
395			if env.SlotFirst {
396				break
397			}
398			cur = env.Parent
399		}
400		return chain, nil
401	}
402	
403	// Slots 返回所有存档槽名。
404	func (a *Archive) Slots() ([]string, error) {
405		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
406		if err != nil {
407			return nil, err
408		}
409		var names []string
410		for _, e := range entries {
411			if e.IsDir() {
412				continue
413			}
414			name := e.Name()
415			if len(name) > 5 && name[len(name)-5:] == ".json" {
416				names = append(names, name[:len(name)-5])
417			}
418		}
