1	package world
2	
3	import (
4		"errors"
5		"os"
6		"syscall"
7	)
8	
9	// Record 是一次成功保存留下的、可供读取的记录。
10	type Record struct {
11		// ID 是记录标识。
12		ID RecordID
13		// Parent 是父记录标识；槽首条记录为空。
14		Parent RecordID
15		// SlotFirst 表示这是其所在槽的首条记录。
16		SlotFirst bool
17		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
18		State State
19	}
20	
21	func acquireSharedLock(dir string) (*fileLock, error) {
22		path := dir + "/lock"
23		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
24		if err != nil {
25			return nil, err
26		}
27		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
28			f.Close()
29			return nil, err
30		}
31		return &fileLock{f: f}, nil
32	}
33	
34	// loadAndVerifyLocked 读取记录文件，校验其内容校验和（校验和已包含
35	// 父记录关系）、父记录是否存在，以及世界数据是否自洽。
36	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
37		env, err := loadRecord(recordPath(a.dir, id))
38		if err != nil {
39			if errors.Is(err, os.ErrNotExist) {
40				return nil, &NotFoundError{Record: id}
41			}
42			return nil, &CorruptError{Record: id, Reason: err.Error()}
43		}
44		if env.ID != id {
45			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
46		}
47		if got := computeChecksum(env); got != env.Checksum {
48			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
49		}
50		// 父记录关系必须落到一个真实存在的记录上。
51		if env.Parent != "" {
52			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
53				if errors.Is(err, os.ErrNotExist) {
54					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
55				}
56				return nil, err
57			}
58		}
59		if err := validateInitialData(InitialData{
60			Seed:       env.State.Seed,
61			Rules:      env.State.Rules,
62			Characters: env.State.Characters,
63		}); err != nil {
64			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
65		}
66		return env, nil
67	}
68	
69	func versionAccepted(version string, accepted []string) bool {
70		for _, v := range accepted {
71			if v == version {
72				return true
73			}
74		}
75		return false
76	}
77	
78	func envToRecord(env *envelope) Record {
79		return Record{
80			ID:        env.ID,
81			Parent:    env.Parent,
82			SlotFirst: env.SlotFirst,
83			State:     cloneState(env.State),
84		}
85	}
86	
87	// Latest 读取槽当前最新记录。
88	//
89	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
90	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（校验和不符、
91	// 父记录缺失、无法解析）时返回 *CorruptError。读取不会改写存档。
92	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
93		if !validSlotName(slot) {
94			return Record{}, &NotFoundError{Slot: slot}
95		}
96		lock, err := acquireSharedLock(a.dir)
97		if err != nil {
98			return Record{}, err
99		}
100		defer lock.release()
101	
102		id, err := a.readLatestLocked(slot)
103		if err != nil {
104			return Record{}, err
105		}
106		env, err := a.loadAndVerifyLocked(id)
107		if err != nil {
108			if ce, ok := err.(*CorruptError); ok {
109				ce.Slot = slot
110			}
111			return Record{}, err
112		}
113		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
114			return Record{}, &VersionRejectedError{
115				Slot:     slot,
116				Record:   id,
117				Version:  env.State.Rules.Version,
118				Accepted: append([]string(nil), acceptedVersions...),
119			}
120		}
121		return envToRecord(env), nil
122	}
123	
124	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
125	//
126	// 与 Latest 一样检查内容校验和（含父记录关系）与规则版本，且记录必须
127	// 属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
128	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
129		if !validSlotName(slot) {
130			return Record{}, &NotFoundError{Slot: slot}
131		}
132		lock, err := acquireSharedLock(a.dir)
133		if err != nil {
134			return Record{}, err
135		}
136		defer lock.release()
137	
138		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
139			return Record{}, err
140		}
141		env, err := a.loadAndVerifyLocked(id)
142		if err != nil {
143			if ce, ok := err.(*CorruptError); ok {
144				ce.Slot = slot
145			}
146			return Record{}, err
147		}
148		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
149			return Record{}, &VersionRejectedError{
150				Slot:     slot,
151				Record:   id,
152				Version:  env.State.Rules.Version,
153				Accepted: append([]string(nil), acceptedVersions...),
154			}
155		}
156		return envToRecord(env), nil
157	}
158	
159	// History 返回槽的历史记录元信息，最新在前，到该槽首条记录为止
160	// （不会跨入分支来源槽）。该方法只做只读遍历，不改写任何数据。
161	func (a *Archive) History(slot string) ([]RecordInfo, error) {
162		if !validSlotName(slot) {
163			return nil, &NotFoundError{Slot: slot}
164		}
165		lock, err := acquireSharedLock(a.dir)
166		if err != nil {
167			return nil, err
168		}
169		defer lock.release()
170	
171		chain, err := a.slotChainLocked(slot)
172		if err != nil {
173			return nil, err
174		}
175		infos := make([]RecordInfo, 0, len(chain))
176		for _, id := range chain {
177			env, err := loadRecord(recordPath(a.dir, id))
178			if err != nil {
179				break
180			}
181			infos = append(infos, RecordInfo{
182				ID:        env.ID,
183				Parent:    env.Parent,
184				SlotFirst: env.SlotFirst,
185				Version:   env.State.Rules.Version,
186			})
187		}
188		return infos, nil
189	}
190	
191	// RecoverLatest 在最新记录损坏或版本不被接受时，沿历史链（最新在前）
