295			t.Fatal(err)
296		}
297		if r0rec.ID != r0.ID {
298			t.Fatal("根记录读取错误")
299		}
300	
301		// 最新记录被截断到无法解析时无法取得父指针，链无法继续 -> 不可恢复。
302		if err := os.Truncate(recordPath(dir, r2), 40); err != nil {
303			t.Fatal(err)
304		}
305		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
306			t.Fatalf("链断裂无法继续时应不可恢复，得到 %T: %v", err, err)
307		}
308	}
