func TestCheckUpgradeNoLimitMeansUnlimited(t *testing.T) {
	a, _ := newTestArchive(t)
	// hero 携带 5 件 gold，上限也是 5；目标规则不设 hero 上限，
	// 因此不应有上限阻碍。
	w, err := NewWorld(InitialData{
		Seed:  1,
