func TestUpgradeConcurrent(t *testing.T) {
	a, dir := newTestArchive(t)
	info := saveBase(t, a, "s")

	const n = 8
	var wg sync.WaitGroup
	var mu sync.Mutex
	wins, conflicts := 0, 0
	errs := make([]error, 0)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			// 每个 goroutine 使用独立的 Archive 实例（独立 flock 句柄）。
			ga, err := Open(dir)
			if err != nil {
				mu.Lock()
				errs = append(errs, err)
				mu.Unlock()
				return
			}
			_, uerr := ga.Upgrade("s", []string{"v1"}, v2Rules(), info.ID)
			mu.Lock()
			defer mu.Unlock()
			switch {
			case uerr == nil:
				wins++
			case isConflict(uerr):
				conflicts++
			default:
				errs = append(errs, uerr)
			}
		}()
	}
	wg.Wait()
	if len(errs) != 0 {
		t.Fatalf("并发升级出现非冲突错误: %v", errs)
	}
	if wins != 1 || conflicts != n-1 {
		t.Fatalf("期望恰好 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
	}
	// 最终槽指向升级后的完整记录。
	a2, _ := Open(dir)
	rec, err := a2.Latest("s", []string{"v1", "v2"})
	if err != nil {
		t.Fatalf("并发升级后最新记录应完好: %v", err)
	}
	if rec.State.Rules.Version != "v2" {
		t.Fatal("胜出记录应使用目标规则")
	}
}

func TestUpgradeVersusReplaceConcurrent(t *testing.T) {
	a, dir := newTestArchive(t)
	info := saveBase(t, a, "s")

	var wg sync.WaitGroup
	var mu sync.Mutex
	wins, conflicts := 0, 0
	errs := make([]error, 0)
	// 一半升级，一半普通覆盖，都基于同一父记录。
	for i := 0; i < 6; i++ {
		wg.Add(2)
		go func() {
			defer wg.Done()
			ga, _ := Open(dir)
			_, err := ga.Upgrade("s", []string{"v1"}, v2Rules(), info.ID)
			mu.Lock()
			defer mu.Unlock()
			if err == nil {
				wins++
			} else if isConflict(err) {
				conflicts++
			} else {
				errs = append(errs, err)
			}
		}()
		go func() {
			defer wg.Done()
			ga, _ := Open(dir)
			w := baseWorld(t)
			_, err := ga.Replace("s", w, info.ID)
			mu.Lock()
			defer mu.Unlock()
			if err == nil {
				wins++
			} else if isConflict(err) {
				conflicts++
			} else {
				errs = append(errs, err)
			}
		}()
	}
	wg.Wait()
	if len(errs) != 0 {
		t.Fatalf("竞争出现非冲突错误: %v", errs)
	}
	if wins != 1 || conflicts != 11 {
		t.Fatalf("期望恰好 1 成功 11 冲突，得到 %d 成功 %d 冲突", wins, conflicts)
	}
}

func isConflict(err error) bool {
	var ce *ConflictError
	return errors.As(err, &ce)
}

